import heapq

class Leaderboard:
    def __init__(self):
        # Dict to store total scores for each player
        self.scores = {}

    def addScore(self, playerId: int, score: int) -> None:
        # Add (or create) the score for playerId
        self.scores[playerId] = self.scores.get(playerId, 0) + score

    def top(self, K: int) -> int:
        # Sum of the K largest scores
        return sum(heapq.nlargest(K, self.scores.values()))

    def reset(self, playerId: int) -> None:
        # Erase the player from the leaderboard (score back to 0)
        self.scores.pop(playerId, None)
